package identitycore

func MFASetupPageHTML(product, codeLabel string) string {
	return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Add extra sign-in protection · ` + product + `</title><link rel="stylesheet" href="/static/app.css"><script src="/static/theme.js"></script></head><body class="auth"><main class="grant-card"><h1>Add extra sign-in protection</h1><p>Open your authenticator app and add Kinosail. Enter the setup key below, or use the setup link if your app supports it.</p><ol class="wizard-help-list"><li>Copy the setup key or setup link into your authenticator app.</li><li>Save every recovery code before you continue. Each code works once.</li><li>Enter the current 6-digit code to confirm the app.</li></ol><p><strong>Setup key</strong><br><code>{{.Secret}}</code></p><p><strong>Setup link</strong><br><code>{{.URI}}</code></p><h2>Recovery codes</h2>{{range .RecoveryCodes}}<code>{{.}}</code><br>{{end}}<p>Store these codes somewhere safe. Each works once.</p><form action="/account/mfa/enable" method="post">{{if .Next}}<input type="hidden" name="next" value="{{.Next}}">{{end}}<label>{{t "` + codeLabel + `"}}<input name="code" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><button>Turn on extra sign-in protection</button></form></main></body></html>`
}
